window.AUTH=window.AUTH||{};window.AUTH["23-367"]={"d":"23-367","id":"2023/23-367","n":"Starbucks Corporation v. McKinney","briefs":[{"k":"petitioner","label":"Brief of petitioner Starbucks Corporation","date":"2024-02-21","url":"https://www.supremecourt.gov/DocketPDF/23/23-367/301020/20240221121804393_Starbucks%20Corp.%20v.%20McKinney%20Petitioner%20Merits%20Br.pdf","side":"pet","n":101},{"k":"respondent","label":"Brief of respondent Kathleen McKinney, Regional Director of Region 15 of the National Labor Relations Board, for and on Behalf of the National Labor Relations Board","date":"2024-03-22","url":"https://www.supremecourt.gov/DocketPDF/23/23-367/305772/20240322184334216_23-367bsUnitedStates.pdf","side":"res","n":82},{"k":"reply","label":"Reply of petitioner Starbucks Corporation","date":"2024-04-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-367/307438/20240412111032380_Starbucks%20Corp.%20v.%20McKinney%20Merits%20Reply%20Brief.pdf","side":"pet","n":41}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r34_e29g.pdf","tr":true,"items":[{"t":"case","label":"Adams Fruit Co. v. Barrett","cite":"494 U.S. 638","y":1990,"id":"1989/88-2035","sc":1,"sum":"Exclusivity provisions in state workers' compensation laws do not bar migrant workers from availing themselves of a private right of action under § 1854.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","2":"14"}},{"t":"case","label":"Ahearn v. Jackson Hosp. Corp.","cite":"351 F.3d 226","y":2003,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/351/226/","op":1,"ar":1,"by":{"0":"35-36","1":"35-37, 40, 41","2":"4"}},{"t":"case","label":"Am. Foreign Serv. Ass’n v. Baker","cite":"895 F.2d 1460","y":1990,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/895/1460/","sum":"Observing that courts play an “auxiliary role” in the statutory scheme and should take care not to “improper[ly] * * * enlarge” that role.","sumSrc":"brief:1","by":{"0":"24","1":"41"}},{"t":"case","label":"Amoco Prod. Co. v. Village of Gambell","cite":"480 U.S. 531","y":1987,"id":"1986/85-1239","sc":1,"op":1,"sum":"Section 810(a) of the Alaska National Interest Lands Conservation Act (ANILCA) provides, inter alia, that, before allowing the use, occupancy, or disposition of public lands that would significantly restrict Alaskan Natives' use of those lands for subsistence, the head of the federal agency having primary jurisdiction over the lands must give notice, conduct a hearing, and determine that the restriction of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26-27","1":"32"}},{"t":"case","label":"Arlook v. S. Lichtenberg & Co.","cite":"952 F.2d 367","y":1992,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/952/367/","by":{"0":"33-34","1":"35"}},{"t":"case","label":"Ashcroft v. Am. C.L. Union","cite":"542 U.S. 656","y":2004,"id":"2003/03-218","sc":1,"sum":"In an interesting 5-to-4 vote, with Justices Kennedy, Stevens, Souter, Thomas and Ginsburg on one side and Chief Justice Rehnquist and Justices Scalia, Breyer and O'Connor on the other, the Court found that Congress had not yet met its burden to show that the COPA requirements were more effective than other methods of preventing minors.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Axon Enter. v. FTC","cite":"598 U.S. 175","y":2023,"id":"2022/21-86","sc":1,"sum":"The statutory review schemes set out in the Securities Exchange Act and Federal Trade Commission Act do not displace a district court’s federal-question jurisdiction over claims challenging as unconstitutional the structure or existence of the SEC or FTC.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"37"}},{"t":"case","label":"Benisek v. Lamone","cite":"585 U.S. 155","y":2018,"id":"2017/17-333","sc":1,"sum":"A case in which the Court upheld the federal district court's denial of a motion for a preliminary injunction by several Republican voters who alleged partisan gerrymandering in Maryland.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Beth Israel Hosp. v. NLRB","cite":"437 U.S. 483","y":1978,"id":"1977/77-152","sc":1,"op":2,"sum":"The Court held that, since 1974, the Act provided employees of nonprofit healthcare institutions with the right to self-organize and bargain collectively, including the right to communicate about the topic at the jobsite. However, an employer may curb that right by showing that special circumstances necessitate the prohibition of communication in order to maintain production or discipline.","sumSrc":"Oyez","by":{"0":"41","1":"13, 27"}},{"t":"case","label":"Biden v. Texas","cite":"597 U.S. 785","y":2022,"id":"2021/21-954","sc":1,"sum":"The Government’s rescission of Migrant Protection Protocols did not violate section 1225 of the Immigration and Nationality Act, and the then-Secretary of Homeland Security’s October 29 Memoranda constituted valid final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"29"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"op":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","2":"14"}},{"t":"case","label":"Boyle v. Zacharie","cite":"31 U.S. 648","y":1832,"id":"scdb/1832-040","sc":1,"sum":"The facts of this case are stated, in part, in the preceding equity case; and in the opinion of the court, delivered by Mr Justice Story.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Brown v. Swann","cite":"35 U.S. 497","y":1836,"id":"scdb/1836-033","sc":1,"sum":"The statute of Virginia against usury, provides that “ any borrower of money or goods, may exhibit a bill in chancery against the lenders, and compel them to discover on oath the money they really lent; and all bargains, contracts or shifts which shall have passed between them relative to such loan or the repayment thereof, and the interest and consideration of the same: and if thereupon it shall appear that more …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"CFTC v. Walsh","cite":"618 F.3d 218","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/618/218/","by":{"0":"44"}},{"t":"case","label":"Chester v. Grane Healthcare Co.","cite":"666 F.3d 87","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/666/87/","op":2,"by":{"0":"33","1":"35","2":"15"}},{"t":"case","label":"Christensen v. Harris County","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"sum":"The Court held 6-3 that \"[n]othing in the FLSA or its implementing regulations prohibits a public employer from compelling the use of compensatory time.\" Justice Thomas wrote for the Court that, \"under the FLSA, an employer is free to require an employee to take time off work, and an employer is also free to use the money it would have paid in wages to cash out accrued compensatory time.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Conkright v. Frommert","cite":"556 U.S. 1401","y":2009,"url":"https://supreme.justia.com/cases/federal/us/556/1401/","sc":1,"by":{"0":"21"}},{"t":"case","label":"Cortez Byrd Chips, Inc. v. Bill Harbert Constr. Co.","cite":"529 U.S. 193","y":2000,"id":"1999/98-1960","sc":1,"sum":"Delivered by Justice David H. Souter, the Court held that the \"FAA's venue provisions are permissive, allowing a motion to confirm, vacate, or modify to be brought either in the district where the award was made or in any district proper under the general venue statute.\" Writing for the Court, Justice Souter reasoned that because both the history and function of the FAA's venue provisions dictate that they were meant to expand, not limit, venue choice, it was appropriate for Cortez Byrd to seek to vacate the arbitrator's award in federal court in Mississippi.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Douds v. Int’l Longshoremen’s Ass’n","cite":"147 F. Supp. 103","y":1956,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./147/103/","by":{"0":"35"}},{"t":"case","label":"Dupree v. Younger","cite":"598 U.S. 729","y":2023,"id":"2022/22-210","sc":1,"sum":"A post-trial motion under Federal Rule of Civil Procedure 50 is not required to preserve for appellate review a purely legal issue resolved at summary judgment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47"}},{"t":"case","label":"eBay Inc. v. MercExchange, L.L.C.","cite":"547 U.S. 388","y":2006,"id":"2005/05-130","sc":1,"sum":"Held that the appeals court's general rule was an unwarranted departure from the traditional four-part test applied to determine whether an injunction is necessary.","sumSrc":"Oyez","by":{"0":"22, 24, 27, 44"}},{"t":"case","label":"EEOC v. Anchor Hocking Corp.","cite":"666 F.2d 1037","y":1981,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/666/1037/","by":{"0":"43"}},{"t":"case","label":"EEOC v. Astra U.S.A., Inc.","cite":"94 F.3d 738","y":1996,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/94/738/","by":{"0":"43"}},{"t":"case","label":"EEOC v. BNSF Ry. Co.","cite":"2022 WL 1265938","y":2022,"court":"D. Neb. Apr. 28","by":{"0":"43"}},{"t":"case","label":"EEOC v. Cosmair, Inc.","cite":"821 F.2d 1085","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/821/1085/","by":{"0":"44"}},{"t":"case","label":"EEOC v. Pac. Press Pub. Ass’n","cite":"535 F.2d 1182","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/535/1182/","by":{"0":"44"}},{"t":"case","label":"Fleischut v. Nixon Detroit Diesel, Inc.","cite":"859 F.2d 26","y":1988,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/859/26/","op":1,"by":{"0":"36","1":"37","2":"6"}},{"t":"case","label":"FTC v. Univ. Health, Inc.","cite":"938 F.2d 1206","y":1991,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/938/1206/","by":{"0":"44"}},{"t":"case","label":"Glacier Nw., Inc. v. Int’l Bhd. of Teamsters","cite":"598 U.S. 771","y":2023,"id":"2022/21-1449","sc":1,"op":2,"sum":"The National Labor Relations Act did not preempt Glacier’s state tort claims related to the destruction of company property during a labor dispute where the Union failed to take reasonable precautions to avoid foreseeable and imminent danger to the property.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"5"}},{"t":"case","label":"Grupo Mexicano de Desarrollo, S. A. v. Alliance Bond Fund, Inc.","cite":"527 U.S. 308","y":1999,"id":"1998/98-231","sc":1,"sum":"The Court held that the District Court lacked the authority to issue a preliminary injunction preventing defendants being sued by creditors from disposing of their assets pending adjudication of the creditor's contract claim for monetary damages because such a remedy was historically unavailable from a court of equity.","sumSrc":"Oyez","by":{"0":"19, 22"}},{"t":"case","label":"Hadsall v. Sunbelt Rentals, Inc.","cite":"993 F.3d 992","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/993/992/","by":{"0":"6"}},{"t":"case","label":"Hall v. Cole","cite":"412 U.S. 1","y":1973,"id":"1972/72-630","sc":1,"sum":"Respondent, expelled from his union for deliberate and malicious vilification of union management following his resolutions un-successfully condemning that management's alleged undemocratic actions and shortsighted policies, regained his union membership in a suit under § 102 of the Labor-Management Reporting and 'Disclosure Act (LMRDA) and was awarded $5,500 in legal fees. The Court of Appeals affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Hecht Co. v. Bowles","cite":"321 U.S. 321","y":1944,"id":"scdb/1943-092","sc":1,"op":18,"sum":"1. Under § 205 (a) of the Emergency Price Control Act of 1942, the grant of an injunction, upon application of the Administrator and a showing that the defendant has engaged in acts or practices violative of § 4 of the Act, is not mandatory but is in the discretion of the court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 26","1":"9, 15, 16","2":"13"}},{"t":"case","label":"Hollingsworth v. Perry","cite":"558 U.S. 183","y":2010,"id":"scdb/2009-018","sc":1,"sum":"Yes. The applicants showed a fair prospect that the Court would grant certiorari and reverse or grant mandamus, because the District Court likely violated 28 U.S.C. § 2071 in amending its local rule, and showed likely irreparable harm with the equities favoring them. The Court stayed the streaming to other courthouses and did not address broadcasting generally.","sumSrc":"AI-generated brief","by":{"0":"20","2":"6"}},{"t":"case","label":"HollyFrontier Cheyenne Refin., LLC v. Renewable Fuels Ass’n","cite":"141 S. Ct. 2172","y":2021,"id":"2020/20-472","sc":1,"sum":"Under the renewable fuel program’s fuel blending requirements for domestic refineries, a small refinery that previously received a hardship exemption may obtain an “extension” under 42 U. S. C. §7545(o)(9)(B)(i) even if the refinery did not seek a hardship exemption every year after initially doing so.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23"}},{"t":"case","label":"John Doe Co. v. CFPB","cite":"849 F.3d 1129","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/849/1129/","op":1,"by":{"0":"37"}},{"t":"case","label":"Kerwin v. Starbucks Corp.","cite":"657 F. Supp. 3d 1002","y":2023,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/657/1002/","by":{"0":"6"}},{"t":"case","label":"Kinney v. Pioneer Press","cite":"881 F.2d 485","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/881/485/","op":3,"by":{"0":"22, 35","1":"22"}},{"t":"case","label":"Kobell v. Suburban Lines, Inc.","cite":"731 F.2d 1076","y":1984,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/731/1076/","by":{"0":"36"}},{"t":"case","label":"Kreisberg v. HealthBridge Mgmt., LLC","cite":"732 F.3d 131","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/732/131/","by":{"0":"37"}},{"t":"case","label":"McKinney v. Ozburn-Hessey Logistics, LLC","cite":"875 F.3d 333","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/875/333/","op":2,"by":{"0":"12-13, 33","1":"35"}},{"t":"case","label":"McKinney v. S. Bakeries, LLC","cite":"786 F.3d 1119","y":2015,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/786/1119/","op":2,"by":{"0":"29","2":"9, 14"}},{"t":"case","label":"Miller v. Cal. Pac. Med. Ctr.","cite":"19 F.3d 449","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/19/449/","op":5,"by":{"0":"33"}},{"t":"case","label":"Miller v. French","cite":"530 U.S. 327","y":2000,"id":"1999/99-224","sc":1,"sum":"The Court held that Congress clearly intended to make operation of the PLRA's automatic stay provision mandatory, precluding courts from exercising their equitable power to enjoin the stay and that the PLRA does not violate separation of powers principles.","sumSrc":"Oyez","by":{"0":"13, 29"}},{"t":"case","label":"Monsanto Co. v. Geertson Seed Farms","cite":"561 U.S. 139","y":2010,"id":"2009/09-475","sc":1,"sum":"The Court held that a district court must conduct an evidentiary hearing to enter an injunction.","sumSrc":"Oyez","by":{"0":"20","2":"3, 13"}},{"t":"case","label":"Muffley v. Spartan Mining Co.","cite":"570 F.3d 534","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/570/534/","op":2,"sum":"Observing that courts should apply the four-part test “in light of the underlying purpose of § 10( j): preserving the Board’s remedial power pending the outcome of its administrative proceedings”.","sumSrc":"brief:1","by":{"0":"23, 33, 36, 48","1":"22, 30, 34","2":"7, 14"}},{"t":"case","label":"Munaf v. Geren","cite":"553 U.S. 674","y":2008,"id":"2007/06-1666","sc":1,"sum":"Held that the habeas corpus statute extends to American citizens held overseas by American forces operating subject to an American chain of command even if part of a larger multinational force.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"op":1,"ar":1,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"0":"19, 22, 38","1":"34, 37, 41"}},{"t":"case","label":"Overstreet v. El Paso Disposal, L.P.","cite":"625 F.3d 844","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/625/844/","op":1,"by":{"0":"34","2":"4"}},{"t":"case","label":"Parker v. Winnipiseogee Lake Cotton & Woolen Co.","cite":"67 U.S. 545","y":1862,"id":"scdb/1862-027","sc":1,"by":{"0":"20"}},{"t":"case","label":"Pharm. Rsch. & Mfrs. of Am. v. Walsh","cite":"538 U.S. 644","y":2003,"id":"2002/01-188","sc":1,"sum":"The Court held, 9-0, that the Pharmaceutical Research and Manufacturers of America had not carried its burden of showing a probability of success on the merits of its Commerce Clause claims and, 6-3, that their showing was insufficient to support a finding that the Medicaid Act pre-empts Maine's Rx Program insofar as it threatens to coerce manufacturers into reducing their prices on non- Medicaid sales.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Phx. Ry. Co. of Ariz. v. Geary","cite":"239 U.S. 277","y":1915,"id":"scdb/1915-039","sc":1,"sum":"The Federal court has jurisdiction of a suit by a railway company against members of a state railroad commission td enjoin the enforcement of an order made by them which deprives the railway company of its property without due process of law.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20","1":"29"}},{"t":"case","label":"Polselli v. IRS","cite":"598 U.S. 432","y":2023,"id":"2022/21-1599","sc":1,"sum":"When the Internal Revenue Service issues a summons pursuant to 26 U. S. C. §7602(a) in aid of collecting a tax liability, the exception to the notice requirement in §7609(c)(2)(D)(i) applies even if the delinquent taxpayer has no legal interest in the accounts or records summoned.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34"}},{"t":"case","label":"Porter v. Warner Holding Co.","cite":"328 U.S. 395","y":1946,"id":"scdb/1945-032","sc":1,"op":2,"sum":"1. In an.enforcement proceeding under § 205 (a) of the Emergency Price Control Act of 1942, a Federal District Court has power to order restitution of rents collected by a landlord in excess of maximums established by regulations issued under the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22","1":"10, 18, 21, 33"}},{"t":"case","label":"R.R. Comm’n of Tex. v. Pullman Co.","cite":"312 U.S. 496","y":1941,"id":"scdb/1940-063","sc":1,"sum":"'Shaw v. Moore, 104 Vt. 529; 162 A. 373; Franzoni v. Ravenna, 105 Vt. 64; 163 A. 564; Anderson v. Olson, 106 Vt. 70; 184 A. 712; L'Ecuyer v. Farnsworth,106 Vt. 180; 170 A. 677;. Garvey v. Michaud, 108 Vt. 226; \"184 A. 712; Kelley v. Anthony, 110 Vt. 490; 8 A. 2d 641. \"Dessereauv. Walker, 105 Vt. 99; 163 A. 632; Farrenv. McMahon, 110 Vt. 55; 1 A. 2d 726; Hunter v. Preston, 105 Vt. 327, 338; 166 A. 17; Hall v. Royce, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Reuben v. FDIC","cite":"760 F. Supp. 934","y":1991,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./760/934/","sum":"Holding that the relevant provision “makes it easier for the Authority to satisfy one major element in the traditional equitable equation,” namely, irreparable injury.","sumSrc":"brief:1","by":{"0":"24","1":"41"}},{"t":"case","label":"Romag Fasteners, Inc v. Fossil, Inc.","cite":"140 S. Ct. 1492","y":2020,"id":"2019/18-1233","sc":1,"sum":"The Court held that under Section 35 of the Lanham Act, a plaintiff does not need to show willful infringement to receive an award of an infringer’s profits for a violation of Section 43(a).","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Russell v. Farley","cite":"105 U.S. 433","y":1881,"id":"scdb/1881-168","sc":1,"by":{"0":"20-21"}},{"t":"case","label":"Sampson v. Murray","cite":"415 U.S. 61","y":1974,"id":"1973/72-403","sc":1,"sum":"Upon being notified that she was' going to be discharged on a specific date from her position as aprobationary Government employee, respondent filed this action claiming that the applicable Civil Service regulations for discharge of probationary employees had not been followed, and seeking a temporary injunction against her dismissal pending an administrative appeal to the Civil Service Commission (CSC). The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"SEC v. Blatt","cite":"583 F.2d 1325","y":1978,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/583/1325/","ar":5,"by":{"0":"44"}},{"t":"case","label":"SEC v. Cavanagh","cite":"155 F.3d 129","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/155/129/","by":{"0":"44"}},{"t":"case","label":"Sharp v. Parents in Cmty. Action, Inc.","cite":"172 F.3d 1034","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/172/1034/","sum":"Holding that “the irreparable harm to be addressed under § 10( j) is the harm to the collective bargaining process or to other protected employee activities”.","sumSrc":"brief:1","by":{"0":"33","1":"22, 30, 41","2":"9, 14"}},{"t":"case","label":"Sharp v. Webco Indus., Inc.","cite":"225 F.3d 1130","y":2000,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/225/1130/","op":1,"by":{"0":"33, 36"}},{"t":"case","label":"Sheeran v. Am. Com. Lines, Inc.","cite":"683 F.2d 970","y":1982,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/683/970/","by":{"0":"12","1":"37"}},{"t":"case","label":"Smith v. Berryhill","cite":"139 S. Ct. 1765","y":2019,"id":"2018/17-1606","sc":1,"sum":"A Social Security Administration Appeals Council dismissal on timeliness grounds of a request for review after a claimant has had an administrative law judge hearing on the merits qualifies as a “final decision . . . made after a hearing” for purposes of allowing judicial review under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40"}},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24-25"}},{"t":"case","label":"Taniguchi v. Kan Pacific Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"sum":"The Court held that the winner of a federal-court lawsuit cannot be reimbursed by the losing party for any document translation costs under 28 U.S.C. § 1920(6).","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"TVA v. Hill","cite":"437 U.S. 153","y":1978,"id":"1977/76-1701","sc":1,"op":2,"sum":"The Supreme Court held that Congress’ continued appropriation of funds did not imply that the Dam project was exempt from the ESA. The operation of the Tellico Dam would wipe out the Snail Darter's habitat, so an injunction was the proper remedy.","sumSrc":"Oyez","by":{"0":"28","1":"34","2":"11"}},{"t":"case","label":"United States v. E.I. du Pont de Nemours & Co.","cite":"366 U.S. 316","y":1961,"id":"1960/55","sc":1,"sum":"This remedy is not adequate, and the District Court is directed to proceed expeditiously to enter a decree requiring du Pont to divest itself completely of the General Motors stock within not to exceed 10 years from the effective date of the decree.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"United States v. Oakland Cannabis Buyers’ Coop.","cite":"532 U.S. 483","y":2001,"id":"2000/00-151","sc":1,"op":4,"ar":2,"sum":"The Court held that there is no medical necessity exception to the Controlled Substances Act's prohibitions on manufacturing and distributing marijuana. \"The statute reflects a determination that marijuana has no medical benefits worthy of an exception, \" wrote Justice Thomas, therefore, \"medical necessity is not a defense to manufacturing and distributing marijuana.\" Justice John Paul Stevens' concurring opinion, which was joined by Justices David H. Souter and Ruth Bader Ginsburg, argued that \"[b]ecause necessity was raised in this case as a defense to distribution, the Court need not venture an opinion on whether the defense is available to anyone other than distributors.\" Justice Stephen G. Breyer took no part in the consideration or decision of the case.","sumSrc":"Oyez","by":{"0":"19, 26","2":"10, 12-13"}},{"t":"case","label":"United States v. Prof. Air Traffic Controllers Org.","cite":"524 F. Supp. 160","y":1981,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./524/160/","by":{"0":"24"}},{"t":"case","label":"United States v. Progressive, Inc.","cite":"467 F. Supp. 990","y":1979,"court":"W.D. Wis.","url":"https://www.courtlistener.com/c/F.%20Supp./467/990/","by":{"0":"45"}},{"t":"case","label":"United States v. Rodgers","cite":"461 U.S. 677","y":1983,"id":"1982/81-1476","sc":1,"sum":"The Court held that section 7403 of the Internal Revenue Code of 1954 does grant the government power to order the sale of a home itself, even if the delinquent taxpayer is not the only one with interest in the property.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"United States v. Szoka","cite":"260 F.3d 516","y":2001,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/260/516/","by":{"0":"24"}},{"t":"case","label":"Weinberger v. Romero-Barcelo","cite":"456 U.S. 305","y":1982,"id":"1981/80-1990","sc":1,"op":5,"sum":"Held that the district court was not obligated to enjoin the Navy from operating on and around Vieques island. He emphasized the traditional flexibility of equitable remedies and courts’ responsibility to balance plaintiffs’ need for an injunction with the public utility of the enjoined action.","sumSrc":"Oyez","by":{"0":"23, 25, 27, 29, 37","1":"19","2":"11"}},{"t":"case","label":"West Virginia v. EPA","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"by":{"0":"21"}},{"t":"case","label":"Winter v. Nat. Res. Def. Council","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"op":12,"ar":8,"sum":"The Court held that the standard for properly granting a preliminary injunction is not based on the \"possibility\" of irreparable harm to marine life, but rather that \"irreparable injury is likely\" in the absence of such an injunction.","sumSrc":"Oyez","by":{"0":"2, 12, 18-21, 47","1":"15, 21, 26, 36","2":"1-3, 6-8, 12, 19, 23-24"}},{"t":"usc","label":"5 U.S.C. § 7123","url":"https://www.law.cornell.edu/uscode/text/5/7123","by":{"0":"24-25, 42"}},{"t":"usc","label":"7 U.S.C. § 13a-1","url":"https://www.law.cornell.edu/uscode/text/7/13a-1","by":{"0":"44"}},{"t":"usc","label":"8 U.S.C. § 1188","url":"https://www.law.cornell.edu/uscode/text/8/1188","by":{"0":"46"}},{"t":"usc","label":"12 U.S.C. § 2607","url":"https://www.law.cornell.edu/uscode/text/12/2607","by":{"0":"46"}},{"t":"usc","label":"15 U.S.C. § 53","url":"https://www.law.cornell.edu/uscode/text/15/53","by":{"0":"44"}},{"t":"usc","label":"16 U.S.C. § 1536","url":"https://www.law.cornell.edu/uscode/text/16/1536","by":{"0":"28"}},{"t":"usc","label":"18 U.S.C. § 3626","url":"https://www.law.cornell.edu/uscode/text/18/3626","stext":{"head":"§3626. Appropriate remedies with respect to prison conditions","paras":[[0,"(a) Requirements for Relief.—"],[1,"(1) Prospective relief.—(A) Prospective relief in any civil action with respect to prison conditions shall extend no further than necessary to correct the violation of the Federal right of a particular plaintiff or plaintiffs. The court shall not grant or approve any prospective relief unless the court finds that such relief is narrowly drawn, extends no further than necessary to correct the violation of the Federal right, and is the least intrusive means necessary to correct the violation of the Federal right. The court shall give substantial weight to any adverse impact on public safety or the operation of a criminal justice system caused by the relief."],[1,"(B) The court shall not order any prospective relief that requires or permits a government official to exceed his or her authority under State or local law or otherwise violates State or local law, unless—"],[2,"(i) Federal law requires such relief to be ordered in violation of State or local law;"],[2,"(ii) the relief is necessary to correct the violation of a Federal right; and"],[2,"(iii) no other relief will correct the violation of the Federal right."],[1,"(C) Nothing in this section shall be construed to authorize the courts, in exercising their remedial powers, to order the construction of prisons or the raising of taxes, or to repeal or detract from otherwise applicable limitations on the remedial powers of the courts."],[1,"(2) Preliminary injunctive relief.—In any civil action with respect to prison conditions, to the extent otherwise authorized by law, the court may enter a temporary restraining order or an order for preliminary injunctive relief. Preliminary injunctive relief must be narrowly drawn, extend no further than necessary to correct the harm the court finds requires preliminary relief, and be the least intrusive means necessary to correct that harm. The court shall give substantial weight to any adverse impact on public safety or the operation of a criminal justice system caused by the preliminary relief and shall respect the principles of comity set out in paragraph (1)(B) in tailoring any preliminary relief. Preliminary injunctive relief shall automatically expire on the date that is 90 days after its entry, unless the court makes the findings required under subsection (a)(1) for the entry of prospective relief and makes the order final before the expiration of the 90-day period."],[1,"(3) Prisoner release order.—(A) In any civil action with respect to prison conditions, no court shall enter a prisoner release order unless—"],[2,"(i) a court has previously entered an order for less intrusive relief that has failed to remedy the deprivation of the Federal right sought to be remedied through the prisoner release order; and"],[2,"(ii) the defendant has had a reasonable amount of time to comply with the previous court orders."],[1,"(B) In any civil action in Federal court with respect to prison conditions, a prisoner release order shall be entered only by a three-judge court in accordance with section 2284 of title 28, if the requirements of subparagraph (E) have been met."],[1,"(C) A party seeking a prisoner release order in Federal court shall file with any request for such relief, a request for a three-judge court and materials sufficient to demonstrate that the requirements of subparagraph (A) have been met."],[1,"(D) If the requirements under subparagraph (A) have been met, a Federal judge before whom a civil action with respect to prison conditions is pending who believes that a prison release order should be considered may sua sponte request the convening of a three-judge court to determine whether a prisoner release order should be entered."],[1,"(E) The three-judge court shall enter a prisoner release order only if the court finds by clear and convincing evidence that—"],[2,"(i) crowding is the primary cause of the violation of a Federal right; and"],[2,"(ii) no other relief will remedy the violation of the Federal right."],[1,"(F) Any State or local official including a legislator or unit of government whose jurisdiction or function includes the appropriation of funds for the construction, operation, or maintenance of prison facilities, or the prosecution or custody of persons who may be released from, or not admitted to, a prison as a result of a prisoner release order shall have standing to oppose the imposition or continuation in effect of such relief and to seek termination of such relief, and shall have the right to intervene in any proceeding relating to such relief."],[0,"(b) Termination of Relief.—"],[1,"(1) Termination of prospective relief.—(A) In any civil action with respect to prison conditions in which prospective relief is ordered, such relief shall be terminable upon the motion of any party or intervener—"],[2,"(i) 2 years after the date the court granted or approved the prospective relief;"],[2,"(ii) 1 year after the date the court has entered an order denying termination of prospective relief under this paragraph; or"],[2,"(iii) in the case of an order issued on or before the date of enactment of the Prison Litigation Reform Act, 2 years after such date of enactment."],[1,"(B) Nothing in this section shall prevent the parties from agreeing to terminate or modify relief before the relief is terminated under subparagraph (A)."],[1,"(2) Immediate termination of prospective relief.—In any civil action with respect to prison conditions, a defendant or intervener shall be entitled to the immediate termination of any prospective relief if the relief was approved or granted in the absence of a finding by the court that the relief is narrowly drawn, extends no further than necessary to correct the violation of the Federal right, and is the least intrusive means necessary to correct the violation of the Federal right."],[1,"(3) Limitation.—Prospective relief shall not terminate if the court makes written findings based on the record that prospective relief remains necessary to correct a current and ongoing violation of the Federal right, extends no further than necessary to correct the violation of the Federal right, and that the prospective relief is narrowly drawn and the least intrusive means to correct the violation."],[1,"(4) Termination or modification of relief.—Nothing in this section shall prevent any party or intervener from seeking modification or termination before the relief is terminable under paragraph (1) or (2), to the extent that modification or termination would otherwise be legally permissible."],[0,"(c) Settlements.—"],[1,"(1) Consent decrees.—In any civil action with respect to prison conditions, the court shall not enter or approve a consent decree unless it complies with the limitations on relief set forth in subsection (a)."],[1,"(2) Private settlement agreements.—(A) Nothing in this section shall preclude parties from entering into a private settlement agreement that does not comply with the limitations on relief set forth in subsection (a), if the terms of that agreement are not subject to court enforcement other than the reinstatement of the civil proceeding that the agreement settled."],[1,"(B) Nothing in this section shall preclude any party claiming that a private settlement agreement has been breached from seeking in State court any remedy available under State law."],[0,"(d) State Law Remedies.—The limitations on remedies in this section shall not apply to relief entered by a State court based solely upon claims arising under State law."],[0,"(e) Procedure for Motions Affecting Prospective Relief.—"],[1,"(1) Generally.—The court shall promptly rule on any motion to modify or terminate prospective relief in a civil action with respect to prison conditions. Mandamus shall lie to remedy any failure to issue a prompt ruling on such a motion."],[1,"(2) Automatic stay.—Any motion to modify or terminate prospective relief made under subsection (b) shall operate as a stay during the period—"],[2,"(A)(i) beginning on the 30th day after such motion is filed, in the case of a motion made under paragraph (1) or (2) of subsection (b); or"],[2,"(ii) beginning on the 180th day after such motion is filed, in the case of a motion made under any other law; and"],[2,"(B) ending on the date the court enters a final order ruling on the motion."],[1,"(3) Postponement of automatic stay.—The court may postpone the effective date of an automatic stay specified in subsection (e)(2)(A) for not more than 60 days for good cause. No postponement shall be permissible because of general congestion of the court's calendar."],[1,"(4) Order blocking the automatic stay.—Any order staying, suspending, delaying, or barring the operation of the automatic stay described in paragraph (2) (other than an order to postpone the effective date of the automatic stay under paragraph (3)) shall be treated as an order refusing to dissolve or modify an injunction and shall be appealable pursuant to section 1292(a)(1) of title 28, United States Code, regardless of how the order is styled or whether the order is termed a preliminary or a final ruling."],[0,"(f) Special Masters.—"],[1,"(1) In general.—(A) In any civil action in a Federal court with respect to prison conditions, the court may appoint a special master who shall be disinterested and objective and who will give due regard to the public safety, to conduct hearings on the record and prepare proposed findings of fact."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3626?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3626. Appropriate remedies with respect to prison conditions","tname":"Crimes and Criminal Procedure","by":{"0":"29"}},{"t":"usc","label":"21 U.S.C. § 882","url":"https://www.law.cornell.edu/uscode/text/21/882","by":{"0":"26"}},{"t":"usc","label":"22 U.S.C. § 4109","url":"https://www.law.cornell.edu/uscode/text/22/4109","by":{"0":"24, 42"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"29 U.S.C. § 153","url":"https://www.law.cornell.edu/uscode/text/29/153","subs":["(d)"],"stext":{"head":"§153. National Labor Relations Board","paras":[[0,"(a) Creation, composition, appointment, and tenure; Chairman; removal of members"],[0,"The National Labor Relations Board (hereinafter called the \"Board\") created by this subchapter prior to its amendment by the Labor Management Relations Act, 1947 [29 U.S.C. 141 et seq.], is continued as an agency of the United States, except that the Board shall consist of five instead of three members, appointed by the President by and with the advice and consent of the Senate. Of the two additional members so provided for, one shall be appointed for a term of five years and the other for a term of two years. Their successors, and the successors of the other members, shall be appointed for terms of five years each, excepting that any individual chosen to fill a vacancy shall be appointed only for the unexpired term of the member whom he shall succeed. The President shall designate one member to serve as Chairman of the Board. Any member of the Board may be removed by the President, upon notice and hearing, for neglect of duty or malfeasance in office, but for no other cause."],[0,"(b) Delegation of powers to members and regional directors; review and stay of actions of regional directors; quorum; seal"],[0,"The Board is authorized to delegate to any group of three or more members any or all of the powers which it may itself exercise. The Board is also authorized to delegate to its regional directors its powers under section 159 of this title to determine the unit appropriate for the purpose of collective bargaining, to investigate and provide for hearings, and determine whether a question of representation exists, and to direct an election or take a secret ballot under subsection (c) or (e) of section 159 of this title and certify the results thereof, except that upon the filing of a request therefor with the Board by any interested person, the Board may review any action of a regional director delegated to him under this paragraph, but such a review shall not, unless specifically ordered by the Board, operate as a stay of any action taken by the regional director. A vacancy in the Board shall not impair the right of the remaining members to exercise all of the powers of the Board, and three members of the Board shall, at all times, constitute a quorum of the Board, except that two members shall constitute a quorum of any group designated pursuant to the first sentence hereof. The Board shall have an official seal which shall be judicially noticed."],[0,"(c) Annual reports to Congress and the President"],[0,"The Board shall at the close of each fiscal year make a report in writing to Congress and to the President summarizing significant case activities and operations for that fiscal year."],[0,"(d) General Counsel; appointment and tenure; powers and duties; vacancy"],[0,"There shall be a General Counsel of the Board who shall be appointed by the President, by and with the advice and consent of the Senate, for a term of four years. The General Counsel of the Board shall exercise general supervision over all attorneys employed by the Board (other than administrative law judges and legal assistants to Board members) and over the officers and employees in the regional offices. He shall have final authority, on behalf of the Board, in respect of the investigation of charges and issuance of complaints under section 160 of this title, and in respect of the prosecution of such complaints before the Board, and shall have such other duties as the Board may prescribe or as may be provided by law. In case of a vacancy in the office of the General Counsel the President is authorized to designate the officer or employee who shall act as General Counsel during such vacancy, but no person or persons so designated shall so act (1) for more than forty days when the Congress is in session unless a nomination to fill such vacancy shall have been submitted to the Senate, or (2) after the adjournment sine die of the session of the Senate in which such nomination was submitted."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/153?type=usc&year=mostrecent&link-type=html"},"head":"§153. National Labor Relations Board","tname":"Labor","by":{"0":"5","1":"3"}},{"t":"usc","label":"33 U.S.C. § 1311","url":"https://www.law.cornell.edu/uscode/text/33/1311","by":{"0":"27"}},{"t":"usc","label":"35 U.S.C. § 283","url":"https://www.law.cornell.edu/uscode/text/35/283","by":{"0":"26"}},{"t":"usc","label":"42 U.S.C. § 262","url":"https://www.law.cornell.edu/uscode/text/42/262","by":{"0":"28"}},{"t":"usc","label":"46 U.S.C. § 2305","url":"https://www.law.cornell.edu/uscode/text/46/2305","by":{"0":"45"}},{"t":"usc","label":"47 U.S.C. § 223","url":"https://www.law.cornell.edu/uscode/text/47/223","by":{"0":"45"}},{"t":"usc","label":"49 U.S.C. § 5122","url":"https://www.law.cornell.edu/uscode/text/49/5122","by":{"0":"45"}},{"t":"usc","label":"50 U.S.C. § 925","url":"https://www.law.cornell.edu/uscode/text/50/925","subs":["(1944)"],"op":1,"tname":"War and National Defense","by":{"0":"26"}},{"t":"usc","label":"52 U.S.C. § 10306","url":"https://www.law.cornell.edu/uscode/text/52/10306","by":{"0":"45"}},{"t":"usc","label":"29 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/29/101","stext":{"head":"§101. Issuance of restraining orders and injunctions; limitation; public policy","paras":[[0,"No court of the United States, as defined in this chapter, shall have jurisdiction to issue any restraining order or temporary or permanent injunction in a case involving or growing out of a labor dispute, except in a strict conformity with the provisions of this chapter; nor shall any such restraining order or temporary or permanent injunction be issued contrary to the public policy declared in this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/101?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§101. Issuance of restraining orders and injunctions; limitation; public policy","tname":"Labor","by":{"0":"29","1":"20"}},{"t":"law","label":"Pub. L. No. 80-101","by":{"0":"22"}},{"t":"reg","label":"29 C.F.R. § 101.4","url":"https://www.ecfr.gov/current/title-29/section-101.4","by":{"0":"5"}},{"t":"case","label":"Amalgamated Clothing Workers v. Richman Bros.","cite":"348 U.S. 511","y":1955,"id":"scdb/1954-049","sc":1,"op":1,"sum":"Under 28 U. S. C. § 2283, the Federal District Court was denied power to enjoin the proceedings in the state court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Bloedorn v. Francisco Foods, Inc.","cite":"276 F.3d 270","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/276/270/","op":3,"by":{"1":"27, 28"}},{"t":"case","label":"Chevron, U.S.A. Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Douds v. Anheuser-Busch, Inc.","cite":"99 F. Supp. 474","y":1951,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./99/474/","by":{"1":"23"}},{"t":"case","label":"Douds v. Local 294","cite":"75 F. Supp. 414","y":1947,"court":"N.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./75/414/","by":{"1":"23","2":"17"}},{"t":"case","label":"FTC v. Consumer Def., LLC","cite":"926 F.3d 1208","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/926/1208/","by":{"1":"42","2":"24"}},{"t":"case","label":"Ford Motor Co. v. NLRB","cite":"441 U.S. 488","y":1979,"id":"1978/77-1806","sc":1,"op":1,"sum":"In-plant cafeteria and vending machine food and beverage prices and services are \"terms and conditions of employment\" subject to mandatory collective bargaining under §§ 8 (a) (5) and 8 (d) of the NLRA.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Frankl v. HTH Corp.","cite":"650 F.3d 1334","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/650/1334/","op":1,"by":{"1":"22","2":"3, 9"}},{"t":"case","label":"Franks Bros. Co. v. NLRB","cite":"321 U.S. 702","y":1944,"id":"scdb/1943-086","sc":1,"op":8,"sum":"1. The National Labor Relations Board acted within its statutory authority in ordering petitioner to bargain collectively with a union which had lost its majority after petitioner had wrongfully refused to bargain with it. 29 U. S. C. § 160 (a), (c).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Frye v. District 1199, Health Care & Soc. Serv. Union","cite":"996 F.2d 141","y":1993,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/996/141/","by":{"1":"32"}},{"t":"case","label":"Gilbertville Trucking Co. v. United States","cite":"371 U.S. 115","y":1962,"id":"1962/40","sc":1,"sum":"The order denying approval of the merger is affirmed; but the judgmaent is reversed in part, and the case is remanded for further proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Jaffee v. Henry Heide, Inc.","cite":"115 F. Supp. 52","y":1953,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./115/52/","by":{"1":"23"}},{"t":"case","label":"Kansas v. Nebraska","cite":"574 U.S. 445","y":2015,"id":"2014/126-orig","sc":1,"sum":"The Court ruled that Nebraska violated a compact apportioning the water resources of the Republican River among Kansas, Nebraska and Colorado.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Kobell v. United Paperworkers Int’l Union","cite":"965 F.2d 1401","y":1992,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/965/1401/","by":{"1":"32"}},{"t":"case","label":"Lebus v. Manning, Maxwell & Moore, Inc.","cite":"218 F. Supp. 702","y":1963,"court":"W.D. La.","url":"https://www.courtlistener.com/c/F.%20Supp./218/702/","sum":"Observing that because Section 10( j) relief “is for the protection of the public interest and in aid of a policy which Congress has made plain,” “the area for the exercise of the traditional discretion not to grant an injunction is much more limited”.","sumSrc":"brief:1","by":{"1":"23"}},{"t":"case","label":"McKennon v. Nashville Banner Pub. Co.","cite":"513 U.S. 352","y":1995,"id":"1994/93-1543","sc":1,"sum":"Alleging that her discharge by respondent Nashville Banner Publishing Company violated the Age Discrimination in Employment Act of 1967 (ADEA), petitioner McKennon filed suit seeking a variety of legal and equitable remedies available under the ADEA, including backpay. After she admitted in her deposition that she had copied several of the Banner's confidential documents during her final year of employment, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Milk Wagon Drivers’ Union, Loc. No. 753 v. Lake Valley Farm Prod.","cite":"311 U.S. 91","y":1940,"id":"scdb/1940-014","sc":1,"op":1,"sum":"A union of milk-wagon drivers, employed by local dairies in delivering milk, mainly from door to door to retail customers, picketed a large number of retail stores which sold, at cut prices on the cash-and-carry plan, milk bought at wholesale from individuals, called \"vendors,\" who delivered it by their own trucks from supplies bought from other dairies under an arrangement whereby the milk that they did not sell …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Monessen Sw. Ry. Co. v. Morgan","cite":"486 U.S. 330","y":1988,"id":"1987/86-1743","sc":1,"sum":"Appellee suffered a permanent back injury while working as a brakeman and conductor for appellant railroad. After returning to work in a less physically demanding position, appellee brought an action under the Federal Employers' Liability Act (FELA) in a Pennsylvania state court, alleging that his injury was attributable to appellant's negligence and that his future earning power had been impaired as a result of his …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Muniz v. Hoffman","cite":"422 U.S. 454","y":1975,"id":"1974/73-1924","sc":1,"sum":"After their request for a jury trial was denied, petitioners, a labor union officer and the union, were adjudged guilty of criminal contempt for violating temporary injunctions issued by the District Court pursuant to § 10 (1) of the National Labor Relations Act (NLRA) against picketing of an employer pending the National Labor Relations Board's final disposition of the employer's unfair labor practice charge …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30, 32"}},{"t":"case","label":"NLRB v. C & C Plywood Corp.","cite":"385 U.S. 421","y":1967,"id":"1966/53","sc":1,"sum":"Respondent, employer, was charged with an unfair labor practice for inaugurating a premium pay plan during the term of a collective bargaining agreement without prior consultation with the union representing its employees, in violation of §§ 8 (a) (5) and (1) of the National Labor Relations Act. The NLRB issued a cease-and-desist order, rejecting respondent's claim that its action was authorized by a provision of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"NLRB v. Electro-Voice, Inc.","cite":"83 F.3d 1559","y":1996,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/83/1559/","op":2,"by":{"1":"31, 36"}},{"t":"case","label":"NLRB v. Erie Resistor Corp.","cite":"373 U.S. 221","y":1963,"id":"1962/288","sc":1,"sum":"Even in the absence of a finding of specific illegal intent and notwithstanding the employer's claim that his action was necessary to continue his operations during a strike, the National Labor Relations Board was justified in finding that it was a violation of § 8 (a) of the National Labor Relations Act for the employer to discriminate between employees who struck and employees who worked during a strike by …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"NLRB v. Fansteel Metallurgical Co.","cite":"306 U.S. 240","y":1939,"id":"scdb/1938-054","sc":1,"sum":"1. Seizure and forcible retention of an employer's factory buildings by employees, in a \"sit-down\" strike, is good cause for their discharge.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30, 32"}},{"t":"case","label":"NLRB v. Gissel Packing Co.","cite":"395 U.S. 575","y":1969,"id":"1968/573","sc":1,"sum":"In Nos. 573 and 691, Unions waged organizational campaigns, obtained authorization cards from a majority of employees in the appropriate bargaining units, and demanded recognition by the employers. The employers refused to bargain, on the ground that the cards were inherently unreliable, and carried out vigorous antiunion campaigns. In one instance the Union did not seek a representation election but filed unfair …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26, 31"}},{"t":"case","label":"NLRB v. Hearst Publ’ns, Inc.","cite":"322 U.S. 111","y":1944,"id":"scdb/1943-041","sc":1,"sum":"1. The meaning of the term \"employee\" in the National Labor Relations Act is to be determined not exclusively by reference to common-law standards, local law, or legal classifications made for other purposes, but with regard also to the history, context and purposes 12 Congress has shown its ability in other statutes to make clear an intent to include materialmen within the meaning of the word \"subcontractor.\" See § …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"NLRB v. J. Weingarten, Inc.","cite":"420 U.S. 251","y":1975,"id":"1974/73-1363","sc":1,"sum":"The employer violated § 8 (a) (1) of the National Labor Relations Act because it interfered with, restrained, and coerced the individual right of an employee, protected by § 7, \"to engage in... concerted activities for... mutual aid or protection... Y' when it denied the employee's request for the presence of her union representative at the investigatory interview that the employee reasonably believed would result …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"NLRB v. United Ins. Co.","cite":"390 U.S. 254","y":1968,"id":"1967/178","sc":1,"op":1,"sum":"The NLRB's determination that the agents were company employees and not independent contractors represented a choice between two fairly conflicting views, and its order should have been enforced by the Court of Appeals. Pp. 256-260. 371 F. 2d 316, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24"}},{"t":"case","label":"Overstreet v. United Bhd. of Carpenters & Joiners","cite":"409 F.3d 1199","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/409/1199/","by":{"1":"40"}},{"t":"case","label":"Pye v. Excel Case Ready","cite":"238 F.3d 69","y":2001,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/238/69/","sum":"Holding that “the ‘discharge of active and open union supporters . . . risks a serious adverse impact on employee interest in unionization’ ”.","sumSrc":"brief:1","by":{"1":"36"}},{"t":"case","label":"SEC v. Zera Fin. LLC","cite":"2023 WL 8269775","y":2023,"court":"C.D. Cal. Oct. 30","by":{"1":"42"}},{"t":"case","label":"Schaub v. Detroit Newspaper Agency","cite":"154 F.3d 276","y":1998,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/154/276/","by":{"1":"37"}},{"t":"case","label":"Schaub v. West Michigan Plumbing & Heating, Inc.","cite":"250 F.3d 962","y":2001,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/250/962/","by":{"1":"35"}},{"t":"case","label":"Seeler v. Trading Port, Inc.","cite":"517 F.2d 33","y":1975,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/517/33/","sum":"Recognizing that this legislative history invoked the Court’s public-interest precedents.","sumSrc":"brief:1","by":{"1":"21"}},{"t":"case","label":"Sure-Tan, Inc. v. NLRB","cite":"467 U.S. 883","y":1984,"id":"1983/82-945","sc":1,"sum":"The Court held that that the NLRB can act to protect the labor rights of illegal immigrants because it serves the broader purpose of labor to have all workers represented, regardless of immigration status. Precedent establishes that the Board can protect the rights of any employee. The petitioners’ actions illegally discouraged union activity and caused the deportation of their employees.","sumSrc":"Oyez","by":{"1":"4, 26"}},{"t":"case","label":"Texas Dep’t of Hous. & Cmty. Affairs v. Inclusive Cmtys. Project, Inc.","cite":"576 U.S. 519","y":2015,"id":"2014/13-1371","sc":1,"sum":"The Court determined that evidence of disparate impact is sufficient to allege a claim that the defendant violated the Fair Housing Act.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"United States v. American Tobacco Co.","cite":"221 U.S. 106","y":1911,"id":"scdb/1910-132","sc":1,"sum":"Standard Oil Co. v. United States, ante, p. 1, followed and reaffirmed as to the construction to be given to the Anti-trust Act of July 2, 1890, c. 647, 26 Stat. 209; ana held that the combination in this case is one in restraint of trade and an attempt to monopolize the business of tobacco in' interstate commerce within the prohibitions of the act.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"United States v. City & Cnty. of San Francisco","cite":"310 U.S. 16","y":1940,"id":"scdb/1939-127","sc":1,"sum":"that the contract is in violation of the Act, and can not be defended upon the ground that the.City has a right to sell through the corporation as its agent. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18","2":"11"}},{"t":"case","label":"United States v. First Nat’l City Bank","cite":"379 U.S. 378","y":1965,"id":"1964/59","sc":1,"op":6,"ar":1,"sum":"The District Court has jurisdiction to preserve the status quo and prevent further dissipation of assets by issuing its temporary injunction \"freezing\" the corporation's account in respondent's foreign branch pending personal service on the corporation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18","2":"13"}},{"t":"case","label":"United States v. Morgan","cite":"307 U.S. 183","y":1939,"id":"scdb/1938-049","sc":1,"sum":"1. Where an order of the Secretary of Agriculture fixing stockyards rates was set aside for procedural defects without judicial determination of the reasonableness of the rates fixed by the order, the moneys representing the difference between the scheduled rates in effect and the lower rates of the order, which were required to be paid into the District Court as a condition to the granting of an interlocutory …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"United Steelworkers v. United States","cite":"361 U.S. 39","y":1959,"id":"1959/504","sc":1,"sum":"The judgment is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17","2":"11"}},{"t":"case","label":"University of Texas v. Camenisch","cite":"451 U.S. 390","y":1981,"id":"1980/80-317","sc":1,"op":2,"sum":"The question whether a preliminary injunction should have been issued is moot because the terms of the injunction have been fully and irrevocably carried out, but, as the Court of Appeals correctly noted, the question whether the University must pay for the interpreter remains for trial on the merits.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Virginian Ry. Co. v. System Fed’n No. 40","cite":"300 U.S. 515","y":1937,"id":"scdb/1936-092","sc":1,"op":2,"sum":"(1) That the duty to \"treat\" with the representative so certified is mandatory. P. 547. (2) The statute does not undertake to compel agreement and does not preclude the employer from entering into individual contracts directly with individual employees, but it requires the employer to \"treat with\" the authorized representative of the employees, -that is, to meet and confer with their representative, to listen to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 33","2":"12"}},{"t":"case","label":"Wisconsin Cent. Ltd. v. United States","cite":"585 U.S. 274","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"1":"14"}},{"t":"law","label":"Pub. L. No. 85-791","url":"https://www.govinfo.gov/link/statute/72/945","by":{"1":"24"}},{"t":"law","label":"Pub. L. No. 86-257","url":"https://www.govinfo.gov/link/statute/73/544","by":{"1":"24"}},{"t":"usc","label":"29 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/29/151","stext":{"head":"§151. Findings and declaration of policy","paras":[[0,"The denial by some employers of the right of employees to organize and the refusal by some employers to accept the procedure of collective bargaining lead to strikes and other forms of industrial strife or unrest, which have the intent or the necessary effect of burdening or obstructing commerce by (a) impairing the efficiency, safety, or operation of the instrumentalities of commerce; (b) occurring in the current of commerce; (c) materially affecting, restraining, or controlling the flow of raw materials or manufactured or processed goods from or into the channels of commerce, or the prices of such materials or goods in commerce; or (d) causing diminution of employment and wages in such volume as substantially to impair or disrupt the market for goods flowing from or into the channels of commerce."],[0,"The inequality of bargaining power between employees who do not possess full freedom of association or actual liberty of contract, and employers who are organized in the corporate or other forms of ownership association substantially burdens and affects the flow of commerce, and tends to aggravate recurrent business depressions, by depressing wage rates and the purchasing power of wage earners in industry and by preventing the stabilization of competitive wage rates and working conditions within and between industries."],[0,"Experience has proved that protection by law of the right of employees to organize and bargain collectively safeguards commerce from injury, impairment, or interruption, and promotes the flow of commerce by removing certain recognized sources of industrial strife and unrest, by encouraging practices fundamental to the friendly adjustment of industrial disputes arising out of differences as to wages, hours, or other working conditions, and by restoring equality of bargaining power between employers and employees."],[0,"Experience has further demonstrated that certain practices by some labor organizations, their officers, and members have the intent or the necessary effect of burdening or obstructing commerce by preventing the free flow of goods in such commerce through strikes and other forms of industrial unrest or through concerted activities which impair the interest of the public in the free flow of such commerce. The elimination of such practices is a necessary condition to the assurance of the rights herein guaranteed."],[0,"It is hereby declared to be the policy of the United States to eliminate the causes of certain substantial obstructions to the free flow of commerce and to mitigate and eliminate these obstructions when they have occurred by encouraging the practice and procedure of collective bargaining and by protecting the exercise by workers of full freedom of association, self-organization, and designation of representatives of their own choosing, for the purpose of negotiating the terms and conditions of their employment or other mutual aid or protection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/151?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§151. Findings and declaration of policy","tname":"Labor","by":{"1":"2, 33","2":"14"}},{"t":"usc","label":"29 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/29/157","stext":{"head":"§157. Right of employees as to organization, collective bargaining, etc.","paras":[[0,"Employees shall have the right to self-organization, to form, join, or assist labor organizations, to bargain collectively through representatives of their own choosing, and to engage in other concerted activities for the purpose of collective bargaining or other mutual aid or protection, and shall also have the right to refrain from any or all of such activities except to the extent that such right may be affected by an agreement requiring membership in a labor organization as a condition of employment as authorized in section 158(a)(3) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/157?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§157. Right of employees as to organization, collective bargaining, etc.","tname":"Labor","by":{"1":"30"}},{"t":"usc","label":"29 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/29/158","subs":["(a)(1)","(a)(3)","(b)"],"stext":{"head":"§158. Unfair labor practices","paras":[[0,"(a) Unfair labor practices by employer"],[0,"It shall be an unfair labor practice for an employer—"],[1,"(1) to interfere with, restrain, or coerce employees in the exercise of the rights guaranteed in section 157 of this title;"],[1,"(2) to dominate or interfere with the formation or administration of any labor organization or contribute financial or other support to it: Provided, That subject to rules and regulations made and published by the Board pursuant to section 156 of this title, an employer shall not be prohibited from permitting employees to confer with him during working hours without loss of time or pay;"],[1,"(3) by discrimination in regard to hire or tenure of employment or any term or condition of employment to encourage or discourage membership in any labor organization: Provided, That nothing in this subchapter, or in any other statute of the United States, shall preclude an employer from making an agreement with a labor organization (not established, maintained, or assisted by any action defined in this subsection as an unfair labor practice) to require as a condition of employment membership therein on or after the thirtieth day following the beginning of such employment or the effective date of such agreement, whichever is the later, (i) if such labor organization is the representative of the employees as provided in section 159(a) of this title, in the appropriate collective-bargaining unit covered by such agreement when made, and (ii) unless following an election held as provided in section 159(e) of this title within one year preceding the effective date of such agreement, the Board shall have certified that at least a majority of the employees eligible to vote in such election have voted to rescind the authority of such labor organization to make such an agreement: Provided further, That no employer shall justify any discrimination against an employee for nonmembership in a labor organization (A) if he has reasonable grounds for believing that such membership was not available to the employee on the same terms and conditions generally applicable to other members, or (B) if he has reasonable grounds for believing that membership was denied or terminated for reasons other than the failure of the employee to tender the periodic dues and the initiation fees uniformly required as a condition of acquiring or retaining membership;"],[1,"(4) to discharge or otherwise discriminate against an employee because he has filed charges or given testimony under this subchapter;"],[1,"(5) to refuse to bargain collectively with the representatives of his employees, subject to the provisions of section 159(a) of this title."],[0,"(b) Unfair labor practices by labor organization"],[0,"It shall be an unfair labor practice for a labor organization or its agents—"],[1,"(1) to restrain or coerce (A) employees in the exercise of the rights guaranteed in section 157 of this title: Provided, That this paragraph shall not impair the right of a labor organization to prescribe its own rules with respect to the acquisition or retention of membership therein; or (B) an employer in the selection of his representatives for the purposes of collective bargaining or the adjustment of grievances;"],[1,"(2) to cause or attempt to cause an employer to discriminate against an employee in violation of subsection (a)(3) or to discriminate against an employee with respect to whom membership in such organization has been denied or terminated on some ground other than his failure to tender the periodic dues and the initiation fees uniformly required as a condition of acquiring or retaining membership;"],[1,"(3) to refuse to bargain collectively with an employer, provided it is the representative of his employees subject to the provisions of section 159(a) of this title;"],[1,"(4)(i) to engage in, or to induce or encourage any individual employed by any person engaged in commerce or in an industry affecting commerce to engage in, a strike or a refusal in the course of his employment to use, manufacture, process, transport, or otherwise handle or work on any goods, articles, materials, or commodities or to perform any services; or (ii) to threaten, coerce, or restrain any person engaged in commerce or in an industry affecting commerce, where in either case an object thereof is—"],[2,"(A) forcing or requiring any employer or self-employed person to join any labor or employer organization or to enter into any agreement which is prohibited by subsection (e);"],[2,"(B) forcing or requiring any person to cease using, selling, handling, transporting, or otherwise dealing in the products of any other producer, processor, or manufacturer, or to cease doing business with any other person, or forcing or requiring any other employer to recognize or bargain with a labor organization as the representative of his employees unless such labor organization has been certified as the representative of such employees under the provisions of section 159 of this title: Provided, That nothing contained in this clause (B) shall be construed to make unlawful, where not otherwise unlawful, any primary strike or primary picketing;"],[2,"(C) forcing or requiring any employer to recognize or bargain with a particular labor organization as the representative of his employees if another labor organization has been certified as the representative of such employees under the provisions of section 159 of this title;"],[2,"(D) forcing or requiring any employer to assign particular work to employees in a particular labor organization or in a particular trade, craft, or class rather than to employees in another labor organization or in another trade, craft, or class, unless such employer is failing to conform to an order or certification of the Board determining the bargaining representative for employees performing such work:"],[1,"Provided, That nothing contained in this subsection shall be construed to make unlawful a refusal by any person to enter upon the premises of any employer (other than his own employer), if the employees of such employer are engaged in a strike ratified or approved by a representative of such employees whom such employer is required to recognize under this subchapter: Provided further, That for the purposes of this paragraph (4) only, nothing contained in such paragraph shall be construed to prohibit publicity, other than picketing, for the purpose of truthfully advising the public, including consumers and members of a labor organization, that a product or products are produced by an employer with whom the labor organization has a primary dispute and are distributed by another employer, as long as such publicity does not have an effect of inducing any individual employed by any person other than the primary employer in the course of his employment to refuse to pick up, deliver, or transport any goods, or not to perform any services, at the establishment of the employer engaged in such distribution;"],[1,"(5) to require of employees covered by an agreement authorized under subsection (a)(3) the payment, as a condition precedent to becoming a member of such organization, of a fee in an amount which the Board finds excessive or discriminatory under all the circumstances. In making such a finding, the Board shall consider, among other relevant factors, the practices and customs of labor organizations in the particular industry, and the wages currently paid to the employees affected;"],[1,"(6) to cause or attempt to cause an employer to pay or deliver or agree to pay or deliver any money or other thing of value, in the nature of an exaction, for services which are not performed or not to be performed; and"],[1,"(7) to picket or cause to be picketed, or threaten to picket or cause to be picketed, any employer where an object thereof is forcing or requiring an employer to recognize or bargain with a labor organization as the representative of his employees, or forcing or requiring the employees of an employer to accept or select such labor organization as their collective bargaining representative, unless such labor organization is currently certified as the representative of such employees:"],[2,"(A) where the employer has lawfully recognized in accordance with this subchapter any other labor organization and a question concerning representation may not appropriately be raised under section 159(c) of this title,"],[2,"(B) where within the preceding twelve months a valid election under section 159(c) of this title has been conducted, or"],[2,"(C) where such picketing has been conducted without a petition under section 159(c) of this title being filed within a reasonable period of time not to exceed thirty days from the commencement of such picketing: Provided, That when such a petition has been filed the Board shall forthwith, without regard to the provisions of section 159(c)(1) of this title or the absence of a showing of a substantial interest on the part of the labor organization, direct an election in such unit as the Board finds to be appropriate and shall certify the results thereof: Provided further, That nothing in this subparagraph (C) shall be construed to prohibit any picketing or other publicity for the purpose of truthfully advising the public (including consumers) that an employer does not employ members of, or have a contract with, a labor organization, unless an effect of such picketing is to induce any individual employed by any other person in the course of his employment, not to pick up, deliver or transport any goods or not to perform any services."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/158?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§158. Unfair labor practices","tname":"Labor","by":{"1":"2, 5, 6, 5, 6, 32"}},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","subs":["(a)","(b)","(c)","(e)"],"stext":{"head":"§160. Prevention of unfair labor practices","paras":[[0,"(a) Powers of Board generally"],[0,"The Board is empowered, as hereinafter provided, to prevent any person from engaging in any unfair labor practice (listed in section 158 of this title) affecting commerce. This power shall not be affected by any other means of adjustment or prevention that has been or may be established by agreement, law, or otherwise: Provided, That the Board is empowered by agreement with any agency of any State or Territory to cede to such agency jurisdiction over any cases in any industry (other than mining, manufacturing, communications, and transportation except where predominantly local in character) even though such cases may involve labor disputes affecting commerce, unless the provision of the State or Territorial statute applicable to the determination of such cases by such agency is inconsistent with the corresponding provision of this subchapter or has received a construction inconsistent therewith."],[0,"(b) Complaint and notice of hearing; answer; court rules of evidence inapplicable"],[0,"Whenever it is charged that any person has engaged in or is engaging in any such unfair labor practice, the Board, or any agent or agency designated by the Board for such purposes, shall have power to issue and cause to be served upon such person a complaint stating the charges in that respect, and containing a notice of hearing before the Board or a member thereof, or before a designated agent or agency, at a place therein fixed, not less than five days after the serving of said complaint: Provided, That no complaint shall issue based upon any unfair labor practice occurring more than six months prior to the filing of the charge with the Board and the service of a copy thereof upon the person against whom such charge is made, unless the person aggrieved thereby was prevented from filing such charge by reason of service in the armed forces, in which event the six-month period shall be computed from the day of his discharge. Any such complaint may be amended by the member, agent, or agency conducting the hearing or the Board in its discretion at any time prior to the issuance of an order based thereon. The person so complained of shall have the right to file an answer to the original or amended complaint and to appear in person or otherwise and give testimony at the place and time fixed in the complaint. In the discretion of the member, agent, or agency conducting the hearing or the Board, any other person may be allowed to intervene in the said proceeding and to present testimony. Any such proceeding shall, so far as practicable, be conducted in accordance with the rules of evidence applicable in the district courts of the United States under the rules of civil procedure for the district courts of the United States, adopted by the Supreme Court of the United States pursuant to section 2072 of title 28."],[0,"(c) Reduction of testimony to writing; findings and orders of Board"],[0,"The testimony taken by such member, agent, or agency or the Board shall be reduced to writing and filed with the Board. Thereafter, in its discretion, the Board upon notice may take further testimony or hear argument. If upon the preponderance of the testimony taken the Board shall be of the opinion that any person named in the complaint has engaged in or is engaging in any such unfair labor practice, then the Board shall state its findings of fact and shall issue and cause to be served on such person an order requiring such person to cease and desist from such unfair labor practice, and to take such affirmative action including reinstatement of employees with or without back pay, as will effectuate the policies of this subchapter: Provided, That where an order directs reinstatement of an employee, back pay may be required of the employer or labor organization, as the case may be, responsible for the discrimination suffered by him: And provided further, That in determining whether a complaint shall issue alleging a violation of subsection (a)(1) or (a)(2) of section 158 of this title, and in deciding such cases, the same regulations and rules of decision shall apply irrespective of whether or not the labor organization affected is affiliated with a labor organization national or international in scope. Such order may further require such person to make reports from time to time showing the extent to which it has complied with the order. If upon the preponderance of the testimony taken the Board shall not be of the opinion that the person named in the complaint has engaged in or is engaging in any such unfair labor practice, then the Board shall state its findings of fact and shall issue an order dismissing the said complaint. No order of the Board shall require the reinstatement of any individual as an employee who has been suspended or discharged, or the payment to him of any back pay, if such individual was suspended or discharged for cause. In case the evidence is presented before a member of the Board, or before an administrative law judge or judges thereof, such member, or such judge or judges as the case may be, shall issue and cause to be served on the parties to the proceeding a proposed report, together with a recommended order, which shall be filed with the Board, and if no exceptions are filed within twenty days after service thereof upon such parties, or within such further period as the Board may authorize, such recommended order shall become the order of the Board and become effective as therein prescribed."],[0,"(d) Modification of findings or orders prior to filing record in court"],[0,"Until the record in a case shall have been filed in a court, as hereinafter provided, the Board may at any time upon reasonable notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any finding or order made or issued by it."],[0,"(e) Petition to court for enforcement of order; proceedings; review of judgment"],[0,"The Board shall have power to petition any court of appeals of the United States, or if all the courts of appeals to which application may be made are in vacation, any district court of the United States, within any circuit or district, respectively, wherein the unfair labor practice in question occurred or wherein such person resides or transacts business, for the enforcement of such order and for appropriate temporary relief or restraining order, and shall file in the court the record in the proceedings, as provided in section 2112 of title 28. Upon the filing of such petition, the court shall cause notice thereof to be served upon such person, and thereupon shall have jurisdiction of the proceeding and of the question determined therein, and shall have power to grant such temporary relief or restraining order as it deems just and proper, and to make and enter a decree enforcing, modifying and enforcing as so modified, or setting aside in whole or in part the order of the Board. No objection that has not been urged before the Board, its member, agent, or agency, shall be considered by the court, unless the failure or neglect to urge such objection shall be excused because of extraordinary circumstances. The findings of the Board with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall be conclusive. If either party shall apply to the court for leave to adduce additional evidence and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the hearing before the Board, its member, agent, or agency, the court may order such additional evidence to be taken before the Board, its member, agent, or agency, and to be made a part of the record. The Board may modify its findings as to the facts, or make new findings by reason of additional evidence so taken and filed, and it shall file such modified or new findings, which findings with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall be conclusive, and shall file its recommendations, if any, for the modification or setting aside of its original order. Upon the filing of the record with it the jurisdiction of the court shall be exclusive and its judgment and decree shall be final, except that the same shall be subject to review by the appropriate United States court of appeals if application was made to the district court as hereinabove provided, and by the Supreme Court of the United States upon writ of certiorari or certification as provided in section 1254 of title 28."],[0,"(f) Review of final order of Board on petition to court"],[0,"Any person aggrieved by a final order of the Board granting or denying in whole or in part the relief sought may obtain a review of such order in any United States court of appeals in the circuit wherein the unfair labor practice in question was alleged to have been engaged in or wherein such person resides or transacts business, or in the United States Court of Appeals for the District of Columbia, by filing in such a court a written petition praying that the order of the Board be modified or set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Board, and thereupon the aggrieved party shall file in the court the record in the proceeding, certified by the Board, as provided in section 2112 of title 28. Upon the filing of such petition, the court shall proceed in the same manner as in the case of an application by the Board under subsection (e), and shall have the same jurisdiction to grant to the Board such temporary relief or restraining order as it deems just and proper, and in like manner to make and enter a decree enforcing, modifying, and enforcing as so modified, or setting aside in whole or in part the order of the Board; the findings of the Board with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall in like manner be conclusive."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/160?type=usc&year=mostrecent&link-type=html"},"op":11,"head":"§160. Prevention of unfair labor practices","tname":"Labor","by":{"1":"2, 2, 3, 3, 3, 13, 26, 3, 13, 26, 2, 4, 9, 13, 28"}},{"t":"law","label":"Pub. L. No. 98-620","url":"https://www.govinfo.gov/link/statute/98/3360","by":{"1":"24"}},{"t":"case","label":"Everport Terminal Servs., Inc. v. NLRB","cite":"47 F.4th 782","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/47/782/","by":{"2":"16"}},{"t":"case","label":"Fibreboard Paper Prods. v. NLRB","cite":"379 U.S. 203","y":1964,"id":"1964/14","sc":1,"sum":"Respondent union, the bargaining representative for a unit of petitioner's maintenance employees, gave timely notice of its desire to modify the existing collective bargaining agreement. Four days before the expiration of the contract, petitioner informed the union that it had determined that substantial savings could be effected by contracting out the maintenance work, and that since it had made a definite decision …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Henderson v. Bluefield Hosp. Co., LLC","cite":"902 F.3d 432","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/902/432/","by":{"2":"8"}},{"t":"case","label":"Hooks v. Nexstar Broad., Inc.","cite":"54 F.4th 1101","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/54/1101/","op":1,"by":{"2":"9"}},{"t":"case","label":"Jama v. Immigr. & Customs Enf’t","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Kinney v. IUOE, Loc. 150","cite":"994 F.2d 1271","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/994/1271/","by":{"2":"8"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18"}},{"t":"case","label":"Lineback v. Spurlino Materials, LLC","cite":"546 F.3d 491","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/546/491/","by":{"2":"14"}},{"t":"case","label":"Loc. 74, Carpenters Union v. NLRB","cite":"341 U.S. 707","y":1951,"id":"scdb/1950-097","sc":1,"sum":"Its finding and order are sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Murphy v. NCRNC, LLC","cite":"474 F. Supp. 3d 542","y":2020,"court":"N.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/474/542/","by":{"2":"23"}},{"t":"case","label":"New York v. Meta Platforms, Inc.","cite":"66 F.4th 288","y":2023,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/66/288/","by":{"2":"4"}},{"t":"case","label":"NLRB v. Acker Indus.","cite":"460 F.2d 649","y":1972,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/460/649/","by":{"2":"16"}},{"t":"case","label":"NLRB v. Transp. Mgmt. Corp.","cite":"462 U.S. 393","y":1983,"id":"1982/82-168","sc":1,"sum":"Acting on unfair labor practice charges filed by an employee of respondent, petitioner National Labor Relations Board found that respondent had discharged the employee, a busdriver, for his union activities, in violation of §§ 8(a)(1) and 8(a)(3) of the National Labor Relations Act. The Board applied its rule that the General Counsel has the burden of persuading the Board by a preponderance of the evidence that an …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Overstreet v. Gunderson Rail Servs., LLC","cite":"587 F. App’x 379","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/587/379/","by":{"2":"7, 9"}},{"t":"case","label":"United States v. Askins & Miller Orthopaedics, P.A.","cite":"924 F.3d 1348","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/924/1348/","by":{"2":"13"}},{"t":"case","label":"United States v. Bacaner","cite":"2021 WL 3508135","y":2021,"court":"M.D. Fla. Aug. 3","by":{"2":"12-13"}},{"t":"usc","label":"21 U.S.C. § 843","url":"https://www.law.cornell.edu/uscode/text/21/843","by":{"2":"12"}}]};